// DEMO_MODE = true: demo Sheet + October 2026 (vs. September). false: real Sheet, the month that just ended.
// DEMO_MODE = true: Sheet demo + octubre 2026 (vs. septiembre). false: Sheet real, el mes que acaba de terminar.
const DEMO_MODE = true;
const SHEET_URL = {
  real: 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_SHEET_ID/edit',
  demo: 'https://docs.google.com/spreadsheets/d/YOUR_DEMO_GOOGLE_SHEET_ID/edit'
};
const FIRMA = 'Tu equipo de automatización';   // who signs the report (the agency that runs the system) / quién firma el informe
const last = $now.setZone('America/Phoenix').minus({ months: 1 });
const r = DEMO_MODE
  ? { sheet: 'demo', desde: '2026-10-01', hasta: '2026-10-31' }
  : { sheet: 'real', desde: last.startOf('month').toFormat('yyyy-MM-dd'), hasta: last.endOf('month').toFormat('yyyy-MM-dd') };
return [{ json: { ...r, sheet_url: SHEET_URL[r.sheet], firma: FIRMA, demo: DEMO_MODE } }];

// Sonnet writes ONE short paragraph (3 sentences) for the owner. It only gets numbers already computed and formatted
// by P36d, and the next node rejects any number that is not in this data.
// Sonnet escribe UN párrafo corto (3 frases) para la dueña. Solo recibe números ya calculados y formateados por P36d,
// y el nodo siguiente rechaza cualquier número que no esté en estos datos.
const MODEL = 'claude-sonnet-5-5';
const m = $input.first().json;
const P = m.periodo, B = m.anterior, n = m.negocio || {};
const es = String(n.idioma_duena || 'en').startsWith('es');
const loc = es ? 'es-MX' : 'en-US';
const f = v => Math.round(v).toLocaleString(loc);
const usd = v => '$' + f(v);
const pct = (a, b) => (b > 0 ? Math.round(100 * (a - b) / b) : null);
const mes = d => DateTime.fromISO(d).setLocale(es ? 'es' : 'en').toFormat('LLLL');
const DATA = {
  month: mes(P.desde), previous_month: mes(B.desde),
  estimated_value: usd(P.total_usd), previous_estimated_value: usd(B.total_usd), value_change_pct: pct(P.total_usd, B.total_usd),
  system_cost: usd(P.costo_sistema_usd), roi_multiple: P.roi_x !== null ? P.roi_x.toFixed(1) + 'x' : null, previous_roi_multiple: B.roi_x !== null ? B.roi_x.toFixed(1) + 'x' : null,
  new_leads: P.leads, previous_new_leads: B.leads, leads_after_hours: P.leads_fuera_horario, avg_response_seconds: P.respuesta_prom_seg,
  bookings_by_assistant: P.citas_agendadas, previous_bookings_by_assistant: B.citas_agendadas,
  bookings_from_follow_up: P.citas_de_nurturing, clients_who_came_back: P.clientas_que_vuelven, recovered_value: usd(P.valor_recuperado_usd),
  no_shows_avoided: P.no_shows_evitados, no_shows_avoided_value: usd(P.valor_no_shows_usd), real_no_show_rate_pct: P.tasa_no_show_pct,
  hours_saved: Math.round(P.horas_ahorradas), hours_value: usd(P.valor_horas_usd),
  average_rating: P.nota_promedio, reviews_requested: P.resenas_pedidas, low_rating_alerts: P.alertas_nota_baja,
  open_cases_now: m.casos_abiertos
};
const system = `You write one short note for the owner of ${n.nombre || 'a med spa'}, inside her monthly report email.
Write exactly 3 sentences in ${es ? 'Spanish (neutral Latin American, use "tú")' : 'English'}:
1) The headline: the estimated value of the month compared with what the system cost.
2) What improved compared with the previous month (pick the 1 or 2 most meaningful items).
3) One practical thing to keep an eye on next month (for example open cases, low-rating alerts or no-shows), without alarm.
Rules (strict):
- Use ONLY numbers that appear in DATA, written exactly as they appear there. Never calculate, round or invent a number, a percentage or a cause.
- If a value is null, do not mention it.
- Warm, direct, business tone. No greeting, no sign-off, no emojis, no markdown, no lists. Never give medical advice.
- Respond ONLY with JSON: {"parrafo": "..."}`;
return [{ json: {
  es, data: DATA,
  claude_body: { model: MODEL, max_tokens: 2000, system, messages: [{ role: 'user', content: 'DATA:\n' + JSON.stringify(DATA, null, 1) }] }
} }];

// Accepts Claude's paragraph only if every number in it exists in DATA. Otherwise a fixed paragraph is used.
// Acepta el párrafo de Claude solo si cada número que trae existe en DATA. Si no, se usa un párrafo fijo.
const DATA = $('Build ROI Prompt').first().json.data;
const r = $input.first().json || {};
const es = $('Build ROI Prompt').first().json.es;
const norm = s => String(s).replace(/[$,%x\s]/gi, '').replace(/\.0$/, '');
const allowed = new Set();
for (const v of Object.values(DATA)) if (v !== null && v !== undefined) for (const t of String(v).match(/\d[\d.,]*/g) || []) { allowed.add(norm(t)); allowed.add(norm(t).replace(/\.$/, '')); }

let parrafo = '', motivo = '';
try {
  const block = (r.content || []).find(b => b.type === 'text');
  if (!block) throw new Error(r.error ? 'api_error' : 'no_text');
  const txt = block.text.trim();
  const j = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
  parrafo = String(j.parrafo || '').replace(/\s+/g, ' ').trim();
  if (!parrafo || parrafo.length > 700) throw new Error('bad_length');
  const bad = (parrafo.match(/\d[\d.,]*/g) || []).map(t => norm(t).replace(/[.,]$/, '')).filter(t => !allowed.has(t));
  if (bad.length) throw new Error('numbers_not_in_data: ' + bad.join(' '));
} catch (e) { motivo = String(e.message || e); parrafo = ''; }

if (!parrafo) {
  // Fixed fallback, same 3-part structure / párrafo fijo de respaldo, misma estructura
  parrafo = es
    ? `En ${DATA.month} el sistema generó un valor estimado de ${DATA.estimated_value}, frente a ${DATA.system_cost} que costó` + (DATA.roi_multiple ? ` (${DATA.roi_multiple}).` : '.')
      + ` Sofía agendó ${DATA.bookings_by_assistant} citas sin recepcionista y se evitaron ${DATA.no_shows_avoided} inasistencias.`
      + (DATA.open_cases_now ? ` Para el próximo mes, revisa los ${DATA.open_cases_now} casos abiertos con tu equipo.` : ' Para el próximo mes, mantén la agenda al día para que Sofía ofrezca horarios reales.')
    : `In ${DATA.month} the system produced an estimated ${DATA.estimated_value} in value, against ${DATA.system_cost} in cost` + (DATA.roi_multiple ? ` (${DATA.roi_multiple}).` : '.')
      + ` Sofía booked ${DATA.bookings_by_assistant} appointments with no front desk and ${DATA.no_shows_avoided} no-shows were avoided.`
      + (DATA.open_cases_now ? ` Next month, review the ${DATA.open_cases_now} open cases with your team.` : ' Next month, keep the calendar up to date so Sofía offers real openings.');
}
return [{ json: { parrafo, fuente: motivo ? 'plantilla' : 'claude', motivo, usage: r.usage || null } }];

// Monthly ROI email body (HTML blocks with the Lumière look, no images) → P32c in internal mode.
// Cuerpo del informe mensual (bloques HTML con el estilo de Lumière, sin imágenes) → P32c en modo interno.
const cfg = $('Config').first().json;
const m = $('Get Metrics').first().json;
const { parrafo } = $input.first().json;
const P = m.periodo, B = m.anterior, n = m.negocio || {}, A = m.supuestos || {};
const es = String(n.idioma_duena || 'en').startsWith('es');
const loc = es ? 'es-MX' : 'en-US';
const f = v => (v === null || v === undefined ? '—' : Math.round(v).toLocaleString(loc));
const usd = v => '$' + f(v);
const dec = v => (v === null || v === undefined ? '—' : Number(v).toFixed(1));
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const mesFmt = d => DateTime.fromISO(d).setLocale(es ? 'es' : 'en').toFormat('LLLL yyyy');
const mes = mesFmt(P.desde), mesAnt = DateTime.fromISO(B.desde).setLocale(es ? 'es' : 'en').toFormat('LLLL');
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
const change = (a, b) => {
  if (a === null || b === null || b === undefined || b === 0) return '—';
  const d = Math.round(100 * (a - b) / b);
  return `<span style="color:${d >= 0 ? '#5B7B4F' : '#A0522D'};">${d >= 0 ? '↑' : '↓'} ${Math.abs(d)} %</span>`;
};
const C = { mist: '#F7F3EE', soft: '#EFE8DF', pale: '#DDD2C4', steel: '#75685C', slate: '#4A3F37', ink: '#2A2420', gold: '#B08D57' };
const SERIF = "'Libre Caslon Condensed', Georgia, 'Times New Roman', serif";
const SANS = "Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif";
const T = es ? {
  kicker: 'INFORME MENSUAL', title: `Tu ${mes} con el sistema`, value: 'Valor estimado del mes',
  roi: x => `${x} lo que pagas por el sistema (${usd(P.costo_sistema_usd)})`, vs: `vs. ${mesAnt}`,
  tiles: [
    ['LEADS ATENDIDOS', f(P.leads), `respuesta en ~${P.respuesta_prom_seg ?? '—'} s · ${f(P.leads_fuera_horario)} fuera de horario`],
    ['CITAS SIN RECEPCIONISTA', f(P.citas_agendadas), `${P.conversion_lead_cita_pct} % de los leads terminó en cita`],
    ['NO-SHOWS EVITADOS', f(P.no_shows_evitados), `≈ ${usd(P.valor_no_shows_usd)} · inasistencia real ${dec(P.tasa_no_show_pct)} %`],
    ['CITAS RECUPERADAS', f(P.citas_de_nurturing + P.clientas_que_vuelven), `${f(P.citas_de_nurturing)} por seguimiento · ${f(P.clientas_que_vuelven)} volvieron · ≈ ${usd(P.valor_recuperado_usd)}`],
    ['HORAS AHORRADAS', '~' + f(P.horas_ahorradas), `≈ ${usd(P.valor_horas_usd)} de recepción`],
    ['REPUTACIÓN', dec(P.nota_promedio) + ' / 5', `${f(P.resenas_pedidas)} reseñas pedidas · ${f(P.alertas_nota_baja)} alertas atajadas`]
  ],
  table: 'Mes contra mes', cols: [cap(DateTime.fromISO(P.desde).setLocale('es').toFormat('LLLL')), cap(mesAnt), 'Cambio'],
  rows: [['Leads nuevos', 'leads'], ['Citas agendadas por Sofía', 'citas_agendadas'], ['Citas recuperadas', null], ['No-shows evitados', 'no_shows_evitados'],
         ['Horas ahorradas', 'horas_ahorradas'], ['Reseñas pedidas', 'resenas_pedidas'], ['Valor estimado', 'total_usd'], ['ROI', 'roi_x']],
  how: 'Cómo lo calculamos',
  howTxt: `Horas: cada tarea que hizo el sistema × los minutos que le tomaría a una persona, a $${A.valor_hora}/h. No-shows evitados: visitas con recordatorio × ${Math.round((A.no_show_base || 0) * 100)} % (inasistencia típica sin sistema) − las inasistencias reales. Citas recuperadas: agendadas después de un seguimiento o un mensaje de retoque, valoradas con el precio "desde" del servicio (consulta = $${A.consulta}). Todos los supuestos están en la hoja ROI y los puedes cambiar.`,
  open: k => `⚠️ Hoy hay ${k} ${k === 1 ? 'caso abierto' : 'casos abiertos'} en Escalamientos esperando a tu equipo.`,
  demo: 'Datos de demostración.', cta: 'Ver los datos', asunto: `📈 Tu informe de ${mes}: ${usd(P.total_usd)} de valor estimado`,
  pre: `${cap(mes)}: ${usd(P.total_usd)} de valor estimado` + (P.roi_x !== null ? `, ${dec(P.roi_x)}x el costo del sistema.` : '.'),
  pie: 'Informe automático del sistema Lumière. Los números salen de tu Google Sheet.'
} : {
  kicker: 'MONTHLY REPORT', title: `Your ${mes} with the system`, value: 'Estimated value this month',
  roi: x => `${x} what you pay for the system (${usd(P.costo_sistema_usd)})`, vs: `vs. ${mesAnt}`,
  tiles: [
    ['LEADS ANSWERED', f(P.leads), `answered in ~${P.respuesta_prom_seg ?? '—'}s · ${f(P.leads_fuera_horario)} after hours`],
    ['BOOKED WITH NO FRONT DESK', f(P.citas_agendadas), `${P.conversion_lead_cita_pct} % of leads booked`],
    ['NO-SHOWS AVOIDED', f(P.no_shows_evitados), `≈ ${usd(P.valor_no_shows_usd)} · actual no-show rate ${dec(P.tasa_no_show_pct)} %`],
    ['RECOVERED BOOKINGS', f(P.citas_de_nurturing + P.clientas_que_vuelven), `${f(P.citas_de_nurturing)} from follow-up · ${f(P.clientas_que_vuelven)} came back · ≈ ${usd(P.valor_recuperado_usd)}`],
    ['HOURS SAVED', '~' + f(P.horas_ahorradas), `≈ ${usd(P.valor_horas_usd)} of front-desk time`],
    ['REPUTATION', dec(P.nota_promedio) + ' / 5', `${f(P.resenas_pedidas)} reviews requested · ${f(P.alertas_nota_baja)} alerts caught`]
  ],
  table: 'Month over month', cols: [cap(DateTime.fromISO(P.desde).setLocale('en').toFormat('LLLL')), cap(mesAnt), 'Change'],
  rows: [['New leads', 'leads'], ['Booked by Sofía', 'citas_agendadas'], ['Recovered bookings', null], ['No-shows avoided', 'no_shows_evitados'],
         ['Hours saved', 'horas_ahorradas'], ['Reviews requested', 'resenas_pedidas'], ['Estimated value', 'total_usd'], ['ROI', 'roi_x']],
  how: 'How we calculate it',
  howTxt: `Hours: every task the system did × the minutes it would take a person, at $${A.valor_hora}/h. No-shows avoided: reminded visits × ${Math.round((A.no_show_base || 0) * 100)} % (typical no-show rate without the system) − actual no-shows. Recovered bookings: booked after a follow-up or touch-up message, valued at the service's starting price (consultation = $${A.consulta}). Every assumption lives in the ROI sheet and you can change it.`,
  open: k => `⚠️ There ${k === 1 ? 'is 1 open case' : `are ${k} open cases`} in Escalamientos waiting for your team.`,
  demo: 'Demo data.', cta: 'See the data', asunto: `📈 Your ${mes} report: ${usd(P.total_usd)} in estimated value`,
  pre: `${cap(mes)}: ${usd(P.total_usd)} in estimated value` + (P.roi_x !== null ? `, ${dec(P.roi_x)}x the system's cost.` : '.'),
  pie: 'Automatic report from the Lumière system. Numbers come from your Google Sheet.'
};
const cell = k => {
  if (k === null) return [f(P.citas_de_nurturing + P.clientas_que_vuelven), f(B.citas_de_nurturing + B.clientas_que_vuelven), change(P.citas_de_nurturing + P.clientas_que_vuelven, B.citas_de_nurturing + B.clientas_que_vuelven)];
  if (k === 'total_usd') return [usd(P[k]), usd(B[k]), change(P[k], B[k])];
  if (k === 'roi_x') return [P[k] === null ? '—' : dec(P[k]) + 'x', B[k] === null ? '—' : dec(B[k]) + 'x', change(P[k], B[k])];
  return [f(P[k]), f(B[k]), change(P[k], B[k])];
};
const tile = ([label, big, sub]) => `<td width="50%" valign="top" style="padding:6px;"><div style="background:${C.mist};border:1px solid ${C.pale};padding:16px 16px 14px;">
  <div style="font-family:${SANS};font-size:10px;letter-spacing:0.18em;color:${C.steel};">${esc(label)}</div>
  <div style="font-family:${SERIF};font-size:34px;line-height:1.1;color:${C.ink};margin-top:6px;">${esc(big)}</div>
  <div style="font-family:${SANS};font-size:12px;line-height:1.45;color:${C.slate};margin-top:4px;">${esc(sub)}</div></div></td>`;
const tilesHtml = [0, 2, 4].map(k => `<tr>${tile(T.tiles[k])}${tile(T.tiles[k + 1])}</tr>`).join('');
const th = `font-family:${SANS};font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:${C.steel};padding:8px 6px;border-bottom:1px solid ${C.pale};`;
const td = `font-family:${SANS};font-size:14px;color:${C.ink};padding:9px 6px;border-bottom:1px solid ${C.soft};`;
const rowsHtml = T.rows.map(([label, k]) => { const [a, b, c] = cell(k); return `<tr><td style="${td}">${esc(label)}</td><td align="right" style="${td}font-weight:500;white-space:nowrap;">${a}</td><td align="right" style="${td}color:${C.steel};white-space:nowrap;">${b}</td><td align="right" style="${td}white-space:nowrap;">${c}</td></tr>`; }).join('');

const html = `
<div style="font-family:${SANS};font-size:11px;letter-spacing:0.3em;color:${C.gold};">${T.kicker}</div>
<div style="font-family:${SERIF};font-size:30px;line-height:1.15;color:${C.ink};margin:8px 0 26px;">${esc(T.title)}</div>
<div style="border-top:1px solid ${C.pale};border-bottom:1px solid ${C.pale};padding:22px 0;margin-bottom:24px;text-align:center;">
  <div style="font-family:${SANS};font-size:11px;letter-spacing:0.2em;text-transform:uppercase;color:${C.steel};">${esc(T.value)}</div>
  <div style="font-family:${SERIF};font-size:54px;line-height:1.05;color:${C.ink};margin:6px 0;">${usd(P.total_usd)}</div>
  ${P.roi_x !== null ? `<div style="font-family:${SANS};font-size:15px;color:${C.slate};"><strong style="color:${C.ink};">${dec(P.roi_x)}x</strong> ${esc(T.roi('').trim())}</div>` : ''}
  <div style="font-family:${SANS};font-size:13px;color:${C.steel};margin-top:6px;">${esc(T.vs)}: ${usd(B.total_usd)} · ${change(P.total_usd, B.total_usd)}</div>
</div>
<p style="margin:0 0 24px;font-family:${SANS};font-size:16px;line-height:1.65;color:${C.ink};">${esc(parrafo)}</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 -6px 24px;">${tilesHtml}</table>
<div style="font-family:${SERIF};font-size:22px;color:${C.ink};margin:8px 0 10px;">${esc(T.table)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-bottom:24px;">
  <tr><td style="${th}"></td><td align="right" style="${th}">${esc(T.cols[0])}</td><td align="right" style="${th}">${esc(T.cols[1])}</td><td align="right" style="${th}">${esc(T.cols[2])}</td></tr>
  ${rowsHtml}
</table>
${m.casos_abiertos ? `<p style="margin:0 0 20px;padding:12px 14px;background:${C.soft};font-family:${SANS};font-size:14px;color:${C.ink};">${esc(T.open(m.casos_abiertos))}</p>` : ''}
<div style="font-family:${SANS};font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:${C.steel};margin-bottom:6px;">${esc(T.how)}</div>
<p style="margin:0 0 18px;font-family:${SANS};font-size:12px;line-height:1.6;color:${C.steel};">${esc(T.howTxt)}${cfg.demo ? ' ' + esc(T.demo) : ''}</p>`;

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(n.email_duena || ''))) return [];
// Inputs of P32c - Lumière Send Email, internal mode / entrada de P32c en modo interno
return [{ json: {
  email: n.email_duena, asunto: T.asunto, mensaje: T.pre, idioma: es ? 'es' : 'en', origen: 'P36',
  interno: true, html_cuerpo: html, cta_texto: T.cta, cta_url: cfg.sheet_url, firma: cfg.firma, pie: T.pie + (cfg.demo ? ' ' + T.demo : '')
} }];
